"""Owned project identity. Icon drawn specifically for this project."""
import base64
from pathlib import Path

NAME = "Motion Tracking"
VERSION = "1.0.1"
ICON = base64.b64decode(b'')


def write_icon(app):
    path = Path(app) / "assets/motion_tracking.ico"
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(ICON)
    return path
